  evt usegs (sd_segD_post sp gp tp t0 t1 t2 (Z_to_bv 64 (stb + 32)) s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc Fb m)
